/* Project model: defaults for new instruments, patterns and sessions, the demo session,
   and normalize(), which gives every project the page holds its complete shape (defaults for what a
   file leaves out, a routing table, a routing identity for every track). */
(function () {
  'use strict';

  const app = window.STApp;
  const { clamp, uid, colors } = app;

  // Built-in tables (generated by the app, project-portable): Basic single cycles and Morph tables.
  const wavetablePath = (name, group = 'Basic') => `builtin:wavetables/${group}/${name}.wav`;

  // New instruments are empty samplers; a "wavetable synth" is a sampler in Wavetable mode on a built-in table.
  function instrumentDefaults(id, name, type = 'sample') {
    return {
      id,
      name,
      type,
      samplePath: '',
      rootNote: 60,
      volume: .7,
      pan: 0,
      tune: 0,
      mode: 'oneshot',
      start: 0,
      end: 1,
      loopStart: 0,
      loopEnd: 1,
      attack: .005,
      decay: .2,
      sustain: .7,
      release: .2,
      cutoff: 18000,
      resonance: 0,
      filterType: 'lowpass',
      drive: 0,
      bitDepth: 16,
      lfoRate: 0,
      lfoSync: false,
      lfoBeats: 1,
      lfoDepth: 0,
      lfoTarget: 'cutoff',
      lfoShape: 'sine',
      lfo2Rate: 0,
      lfo2Sync: false,
      lfo2Beats: 1,
      lfo2Depth: 0,
      lfo2Target: 'cutoff',
      lfo2Shape: 'sine',
      filterAttack: .005,
      filterDecay: .2,
      filterSustain: 0,
      filterRelease: .2,
      filterEnvAmount: 0,
      sliceCount: 16,
      grainSize: .08,
      grainPosition: .5,
      grainDensity: 2,
      grainSpray: 0,
      grainPitchSpread: 0,
      grainScan: 0,
      grainReverse: 0,
      grainStereo: 0,
      wavetablePosition: 0,
      wavetableFrameSize: 0,
      plugin: null,
      midiInput: 0,
      midiOutput: 0,
      midiInputChannel: 0,
      midiChannel: 1,
      monitor: false
    };
  }

  function wavetableInstrument(id, name, table = 'Saw', group = 'Basic', extra = {}) {
    const noise = group === 'Basic' && table === 'Noise';
    return { ...instrumentDefaults(id, name, 'sample'), samplePath: wavetablePath(table, group),
      mode: noise ? 'forward' : 'wavetable', ...extra };
  }

  function emptyPattern(id = 0, length = 64, tracks = 8) {
    return {
      id,
      name: 'Pattern ' + String(id + 1).padStart(2, '0'),
      length,
      steps: Array.from({ length: tracks }, () => Array(length).fill(null)),
      automation: []
    };
  }

  function blankProject() {
    return normalize({
      name: 'Untitled session',
      bpm: 120,
      tracks: [{
        id: 0,
        name: 'Track 01',
        color: colors[0],
        volume: .8,
        pan: 0,
        instrument: 0,
        delaySend: 0,
        reverbSend: 0
      }]
    });
  }

  function demoProject() {
    const names = ['Velvet bass', 'Glass keys', 'Warm pad', 'Kick', 'Snare', 'Closed hat', 'Open hat', 'Pulse'];
    const tables = ['Saw', 'Sine', 'Triangle', 'Sine', 'Noise', 'Noise', 'Noise', 'Square'];
    const inst = names.map((n, i) => wavetableInstrument(i, n, tables[i]));
    Object.assign(inst[0], {
      cutoff: 1100,
      resonance: .18,
      attack: .008,
      decay: .22,
      sustain: .32,
      release: .16,
      volume: .38
    });
    Object.assign(inst[1], {
      attack: .002,
      decay: .65,
      sustain: .08,
      release: .42,
      volume: .6,
      lfoRate: 4,
      lfoDepth: .02
    });
    Object.assign(inst[2], {
      attack: .3,
      decay: 1,
      sustain: .65,
      release: .7,
      cutoff: 1800,
      volume: .2
    });
    Object.assign(inst[3], {
      attack: .001,
      decay: .15,
      sustain: 0,
      release: .06,
      volume: .9,
      rootNote: 36
    });
    Object.assign(inst[4], {
      attack: .001,
      decay: .10,
      sustain: 0,
      release: .06,
      volume: .32,
      cutoff: 6500
    });
    Object.assign(inst[5], {
      attack: .001,
      decay: .024,
      sustain: 0,
      release: .012,
      volume: .15,
      filterType: 'highpass',
      cutoff: 7000
    });
    Object.assign(inst[6], {
      attack: .001,
      decay: .16,
      sustain: 0,
      release: .08,
      volume: .12,
      filterType: 'highpass',
      cutoff: 6500
    });
    Object.assign(inst[7], {
      attack: .005,
      decay: .14,
      sustain: .05,
      release: .1,
      volume: .12,
      cutoff: 2400
    });
    const project = {
      version: 1,
      name: 'Midnight transmission',
      bpm: 116,
      linesPerBeat: 4,
      swing: .06,
      masterVolume: .65,
      activePattern: 0,
      tracks: names.map((n, i) => ({
        id: i,
        name: n,
        color: colors[i],
        volume: i === 2 ? .7 : .8,
        pan: i === 1 ? -.18 : i === 7 ? .24 : 0,
        mute: false,
        solo: false,
        instrument: i,
        delaySend: i === 1 ? .28 : i === 7 ? .2 : 0,
        reverbSend: i === 1 ? .25 : i === 2 ? .38 : 0
      })),
      instruments: inst,
      patterns: [],
      sequence: [0, 0, 1, 1],
      loopSong: true,
      delay: { time: .375, feedback: .35, mix: .3 },
      reverb: { size: .7, damping: .4, mix: .25 },
      audioPlugins: []
    };
    for (let p = 0; p < 2; p++) {
      const pat = emptyPattern(p);
      pat.name = p ? 'Night drive · B' : 'Night drive · A';
      const base = p ? 41 : 38;
      const put = (t, r, n, v = 100, extra = {}) => pat.steps[t][r] = {
        note: n,
        instrument: t,
        velocity: v,
        gate: .8,
        ...extra
      };
      for (let r = 0; r < 64; r += 16) {
        put(0, r, base, 98);
        put(0, r + 6, base + 12, 80);
        put(0, r + 10, base + 7, 88);
        put(0, r + 14, base, 76);
        put(2, r, base + 24, 65, { gate: 3.8, chord: [0, 3, 7] });
        put(3, r, 36, 116);
        put(3, r + 8, 36, 105);
        put(4, r + 4, 60, 90);
        put(4, r + 12, 60, 97);
        for (let h = 0; h < 16; h += 2) put(5, r + h, 60, h % 4 === 0 ? 76 : 50);
        put(6, r + 10, 60, 52);
        [0, 3, 7, 10].forEach((interval, k) => put(1, r + k * 4, base + 36 + interval, k % 2 ? 72 : 84, { gate: .55 }));
        put(7, r + 7, base + 24, 55);
        put(7, r + 15, base + 31, 63);
      }
      pat.automation = [{
        id: uid(),
        track: 0,
        target: 'cutoff',
        name: 'Bass · filter cutoff',
        interpolation: 'linear',
        points: [{ row: 0, value: 750 }, { row: 31, value: 2100 }, { row: 63, value: 850 }]
      }];
      project.patterns.push(pat);
    }
    return normalize(project);
  }

  function normalize(p) {
    if (!p || typeof p !== 'object') return demoProject();
    p.version = 1;
    p.name = p.name || 'Untitled session';
    p.bpm = p.bpm || 120;
    p.linesPerBeat = p.linesPerBeat || 4;
    p.timeSignature = {
      numerator: clamp(Number(p.timeSignature?.numerator) || 4, 1, 16),
      denominator: [2, 4, 8, 16].includes(Number(p.timeSignature?.denominator))
          ? Number(p.timeSignature.denominator)
          : 4
    };
    // Every project has a routing table with its four collections (without buses: tracks into Master).
    p.routing = { buses: [], outputs: {}, sends: [], sidechains: [], ...(p.routing && typeof p.routing === 'object' ? p.routing : {}) };
    p.metronome = !!p.metronome;
    p.metronomeVolume = p.metronomeVolume ?? .4;
    p.masterVolume = p.masterVolume ?? .7;
    p.activePattern = p.activePattern || 0;
    p.tracks = p.tracks?.length ? p.tracks : [{ id: 0, name: 'Track 01', volume: .8, pan: 0, instrument: 0 }];
    p.instruments = p.instruments?.length ? p.instruments : [instrumentDefaults(0, 'Instrument 01')];
    p.instruments = p.instruments.map((x, i) => ({ ...instrumentDefaults(i, 'Instrument ' + (i + 1)), ...x }));
    p.patterns = p.patterns?.length ? p.patterns : [emptyPattern(0, 64, p.tracks.length)];
    p.patterns.forEach((pat, i) => {
      pat.id = pat.id ?? i;
      pat.length = pat.length || 64;
      pat.name = pat.name || 'Pattern ' + (i + 1);
      pat.steps = pat.steps || [];
      for (let t = 0; t < p.tracks.length; t++) {
        pat.steps[t] = pat.steps[t] || [];
        pat.steps[t].length = pat.length;
        for (let r = 0; r < pat.length; r++) pat.steps[t][r] = pat.steps[t][r] || null;
      }
      pat.automation = pat.automation || [];
    });
    app.normalizeNoteColumns?.(p);
    p.sequence = p.sequence?.length ? p.sequence : [0];
    p.delay = { time: .375, feedback: .35, mix: .3, ...p.delay };
    p.reverb = { size: .7, damping: .4, mix: .25, ...p.reverb };
    p.audioPlugins = p.audioPlugins || [];
    window.STRoutingProject.ensureTrackIDs(p, uid);
    window.STGroups.normalize(p);
    window.STRoutingProject.pruneOrphanPlugins(p);
    return p;
  }

  /* Note length. A step's gate is its length in pattern rows; gate 0 is no gate: tracker semantics, the note
     sounds until the next note on its track, an OFF/CUT or the end of a one-shot sample. New notes get no gate.
     A step without a gate key is DEFAULT_GATE rows long. */
  const DEFAULT_GATE = .8;
  function stepGate(step) {
    if (!step || step.note < 0) return null;
    const gate = step.gate === undefined || step.gate === null ? DEFAULT_GATE : Number(step.gate);
    return gate > 0 ? Math.min(256, Math.max(.01, gate)) : null;
  }
  const gateText = step => {
    const gate = stepGate(step);
    return gate === null ? '—' : String(Math.round(gate * 100) / 100);
  };
  // The pattern editor's Gate column is a per-project view preference (project.viewState, saved with the
  // session but never an Undo step). Hidden by default; live recording measures held notes only while shown.
  const gateColumnShown = (p = app.state?.project) => !!p?.viewState?.gateColumn;

  Object.assign(app, {
    instrumentDefaults, wavetablePath, wavetableInstrument, emptyPattern, blankProject, demoProject, normalize,
    DEFAULT_GATE, stepGate, gateText, gateColumnShown
  });
})();
